<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import ConfigForm from './ConfigForm.vue'
import { Activity, ArrowUpRight, Boxes, Check, ChevronDown, CircleHelp, Command, Gamepad2, LayoutDashboard, ListChecks, LogOut, MessageSquareText, Plus, Radio, Search, Server, Settings2, Shield, Trash2, UserRound, Users, X } from '@lucide/vue'

type Kind = 'adapters' | 'servers' | 'players' | 'social-accounts' | 'groups' | 'whitelist' | 'blacklist' | 'commands' | 'ai-providers' | 'image-templates' | 'plugins' | 'settings' | 'sync-rules' | 'chat-images' | 'placeholders' | 'player-statistics' | 'skins'
type Entry = { id: string; kind: Kind; name: string; detail: string; enabled: boolean; createdAt: string; updatedAt: string }
type LogEntry = { id: string; time: string; level: string; source: string; message: string; requestId?: string }
type LogPage = { items: LogEntry[]; total: number; limit: number; offset: number }
type LogStatus = { persistent: boolean; retentionDays: number; maxRows: number; droppedWrites: number; failedWrites: number }
type AdapterStatus = { state: 'stopped' | 'starting' | 'connected' | 'reconnecting' | 'stopping' | 'failed'; lastError?: string; reconnectCount: number; selfId?: string; nickname?: string }
type BridgeStatus = { serverId: string; serverName: string; state: 'offline' | 'online'; pluginVersion?: string; onlinePlayers: number; lastSeenAt?: string }
const nav = [
  { id: 'overview', label: '概览', icon: LayoutDashboard, group: '概览' },
  { id: 'adapters', label: '平台适配器', icon: Radio, group: '接入', kind: 'adapters' as Kind },
  { id: 'servers', label: 'Minecraft 服务器', icon: Gamepad2, group: '接入', kind: 'servers' as Kind },
  { id: 'groups', label: '群组', icon: MessageSquareText, group: '消息', kind: 'groups' as Kind },
  { id: 'sync-rules', label: '同步规则', icon: Boxes, group: '消息', kind: 'sync-rules' as Kind },
  { id: 'players', label: '玩家与绑定', icon: Users, group: '玩家', kind: 'players' as Kind },
  { id: 'whitelist', label: '白名单', icon: ListChecks, group: '玩家', kind: 'whitelist' as Kind },
  { id: 'blacklist', label: '黑名单', icon: Shield, group: '玩家', kind: 'blacklist' as Kind },
  { id: 'commands', label: '命令', icon: Command, group: '自动化', kind: 'commands' as Kind },
  { id: 'logs', label: '运行日志', icon: Activity, group: '运维' },
]
const selected = ref('overview'), entries = ref<Entry[]>([]), adapters = ref<Entry[]>([]), servers = ref<Entry[]>([]), logs = ref<LogEntry[]>([]), counts = ref<Record<string, number>>({}), loading = ref(false), error = ref(''), toast = ref(''), query = ref(''), modal = ref(false), apiOnline = ref(false), updatedAt = ref('')
const adapterStatuses = ref<Record<string, AdapterStatus>>({})
const bridgeStatuses = ref<Record<string, BridgeStatus>>({})
const logQuery = ref(''), logLevel = ref(''), logComponent = ref(''), logRequestID = ref(''), logFrom = ref(''), logTo = ref(''), logsTotal = ref(0), logsOffset = ref(0), logStatus = ref<LogStatus | null>(null), logPersistence = ref(true), logRetentionDays = ref(30), logMaxRows = ref(100000), savingLogSettings = ref(false)
const authChecked = ref(false), authenticated = ref(false), authRequired = ref(true), authBusy = ref(false), authError = ref(''), authToken = ref('')
const editing = ref<Entry | null>(null), name = ref(''), detail = ref('{}'), enabled = ref(true), adapterType = ref('Onebot11'), modalError = ref(''), initialDetail = ref('{}')
const onebotURL = ref('ws://127.0.0.1:3001/'), onebotToken = ref(''), onebotTokenConfigured = ref(false), onebotHeartbeat = ref(true), onebotHeartbeatInterval = ref(15000)
const qqAppID = ref(''), qqAppSecret = ref(''), qqAppSecretConfigured = ref(false), qqIntents = ref(1107296769), qqAPIBase = ref(''), qqGatewayURL = ref(''), qqTokenURL = ref(''), qqGuilds = ref(true), qqGuildMessages = ref(true), qqGroupMessages = ref(true), qqGuildAtMessages = ref(true)
const serverOptions = ref<{ value: string; label: string }[]>([]), adapterOptions = ref<{ value: string; label: string }[]>([])
const current = computed(() => nav.find(item => item.id === selected.value)!), kind = computed(() => current.value.kind), title = computed(() => current.value.label)
const filtered = computed(() => entries.value.filter(item => `${item.name} ${item.detail}`.toLowerCase().includes(query.value.toLowerCase())))
const groups = ['概览', '接入', '消息', '玩家', '自动化', '运维']
const descriptions: Record<string, string> = { adapters: 'OneBot 11 与 QQ 官方 Bot 连接、运行诊断与消息 API。', servers: 'Minecraft 实例配置。桥接端连接能力仍在移植。', players: '玩家资料与社交账号绑定记录。', groups: '适配器发现的社交群组。', whitelist: '服务器准入名单。', blacklist: '封禁账号与备注。', commands: '自定义命令定义。命令执行引擎仍在移植。', settings: '实例级运行参数。', 'sync-rules': '群与服务器之间的消息路由规则。' }
const recentActivity = computed(() => [...logs.value].sort((a, b) => Date.parse(b.time) - Date.parse(a.time)).slice(0, 5))
const dashboardStats = computed(() => [
  { label: '平台适配器', value: counts.value.adapters ?? 0, note: '已保存配置', icon: Radio, tone: 'mint' },
  { label: 'Minecraft 服务器', value: counts.value.servers ?? 0, note: '服务器配置', icon: Server, tone: 'blue' },
  { label: '玩家资料', value: counts.value.players ?? 0, note: '已登记玩家', icon: UserRound, tone: 'amber' },
  { label: '自定义命令', value: counts.value.commands ?? 0, note: '命令配置', icon: Command, tone: 'rose' },
])
function formatAdapterType(item: Entry) { try { return JSON.parse(item.detail || '{}').adapterType ?? '社交平台适配器' } catch { return '社交平台适配器' } }
async function api<T>(url: string, init?: RequestInit): Promise<T> { const response = await fetch(url, { ...init, credentials: 'same-origin', headers: { 'Content-Type': 'application/json', ...init?.headers } }); if (!response.ok) { if (response.status === 401 && !url.startsWith('/api/auth/')) authenticated.value = false; const body = await response.json().catch(() => ({})); throw new Error(body.message ?? `请求失败 (${response.status})`) } if (response.status === 204) return undefined as T; return response.json() as Promise<T> }
async function loadLogs(offset = logsOffset.value) { const params = new URLSearchParams({ limit: '100', offset: String(offset) }); if (logLevel.value) params.set('level', logLevel.value); if (logComponent.value) params.set('component', logComponent.value); if (logRequestID.value.trim()) params.set('requestId', logRequestID.value.trim()); if (logQuery.value.trim()) params.set('q', logQuery.value.trim()); if (logFrom.value) params.set('from', new Date(logFrom.value).toISOString()); if (logTo.value) params.set('to', new Date(logTo.value).toISOString()); const [page, status] = await Promise.all([api<LogPage>(`/api/logs?${params}`), api<LogStatus>('/api/logs/status')]); logs.value = page.items; logsTotal.value = page.total; logsOffset.value = page.offset; if (!logStatus.value) { logPersistence.value = status.persistent; logRetentionDays.value = status.retentionDays; logMaxRows.value = status.maxRows } logStatus.value = status }
async function saveLogSettings() { savingLogSettings.value = true; error.value = ''; try { const saved = await api<LogStatus>('/api/logs/settings', { method: 'PUT', body: JSON.stringify({ persistent: logPersistence.value, retentionDays: logRetentionDays.value, maxRows: logMaxRows.value }) }); logStatus.value = saved; toast.value = '日志策略已保存'; setTimeout(() => toast.value = '', 2200); await loadLogs(0) } catch (e) { error.value = e instanceof Error ? e.message : '日志策略保存失败' } finally { savingLogSettings.value = false } }
async function loadAdapterStatuses() { const next: Record<string, AdapterStatus> = {}; await Promise.all(adapters.value.map(async item => { try { next[item.id] = await api<AdapterStatus>(`/api/adapter/${item.id}/status`) } catch { next[item.id] = { state: 'failed', reconnectCount: 0 } } })); adapterStatuses.value = next }
async function load() { if (selected.value === 'logs') { loading.value = true; error.value = ''; try { await loadLogs(0) } catch (e) { error.value = e instanceof Error ? e.message : '加载失败' } finally { loading.value = false }; return } if (!kind.value) return; loading.value = true; error.value = ''; try { if (selected.value === 'adapters') { entries.value = await api<Entry[]>('/api/adapter/list'); adapters.value = entries.value; await loadAdapterStatuses() } else { entries.value = await api<Entry[]>(`/api/records?kind=${kind.value}`); if (selected.value === 'servers') { servers.value = entries.value; await loadBridgeStatuses() } } } catch (e) { error.value = e instanceof Error ? e.message : '加载失败' } finally { loading.value = false } }
async function dashboard() { try { const [summary, adapterItems, serverItems, recent] = await Promise.all([api<{ counts: Record<string, number> }>('/api/dashboard/data'), api<Entry[]>('/api/adapter/list'), api<Entry[]>('/api/records?kind=servers'), api<LogPage>('/api/logs?limit=100')]); counts.value = summary.counts; adapters.value = adapterItems; servers.value = serverItems; logs.value = recent.items; await Promise.all([loadAdapterStatuses(), loadBridgeStatuses()]); apiOnline.value = true; updatedAt.value = new Date().toLocaleTimeString('zh-CN'); error.value = '' } catch { apiOnline.value = false; updatedAt.value = '' } }
async function initializeConsole() { try { const session = await api<{ authenticated: boolean; authRequired: boolean }>('/api/auth/session'); authRequired.value = session.authRequired; authenticated.value = session.authenticated; authChecked.value = true; if (authenticated.value) { void dashboard(); void load() } } catch (e) { authError.value = e instanceof Error ? e.message : '无法连接 Go API'; authChecked.value = true } }
async function submitAuth() { authBusy.value = true; authError.value = ''; try { await api('/api/auth/login', { method: 'POST', body: JSON.stringify({ token: authToken.value }) }); authToken.value = ''; authenticated.value = true; void dashboard(); void load() } catch (e) { authError.value = e instanceof Error ? e.message : '身份验证失败' } finally { authBusy.value = false } }
async function loadBridgeStatuses() { try { const items = await api<BridgeStatus[]>('/api/bridge/status'); bridgeStatuses.value = Object.fromEntries(items.map(item => [item.serverId, item])) } catch { bridgeStatuses.value = {} } }
function bridgeStateLabel(state?: BridgeStatus['state']) { return ({ offline: '未连接', online: '运行中' } as const)[state ?? 'offline'] }
function serverTokenOf(item: Entry) { try { return JSON.parse(item.detail || '{}').token ?? '未生成' } catch { return '未生成' } }
async function rotateToken() { if (!editing.value) return; if (!confirm('重新生成令牌后旧令牌立即失效，需要同步更新 Minecraft 插件配置。继续？')) return; try { const result = await api<{ token: string }>(`/api/servers/${editing.value.id}/token`, { method: 'POST' }); const parsed = JSON.parse(detail.value || '{}'); parsed.token = result.token; detail.value = JSON.stringify(parsed, null, 2); toast.value = '新令牌已生成，请更新插件配置'; setTimeout(() => toast.value = '', 3000) } catch (e) { error.value = e instanceof Error ? e.message : '生成令牌失败' } }
watch(selected, () => { query.value = ''; if (!authenticated.value) return; if (selected.value === 'overview') void dashboard(); else void load() })
let logRefresh: number | undefined
onMounted(() => { void initializeConsole(); logRefresh = window.setInterval(() => { if (!apiOnline.value || !authenticated.value) return; if (selected.value === 'overview') void dashboard(); else if (selected.value === 'logs') void loadLogs().catch(() => {}); else if (selected.value === 'adapters') void load().catch(() => {}) }, 15000) })
onUnmounted(() => { if (logRefresh) window.clearInterval(logRefresh) })
function openDocs() { window.open('https://docs.inectar.cn/docs/easybot/intro', '_blank', 'noopener') }
async function signOut() { try { await api('/api/auth/logout', { method: 'POST' }) } catch { /* 服务不可用时也清理页面状态。 */ } authenticated.value = false; authToken.value = '' }
function resetAdapterForm() { onebotURL.value = 'ws://127.0.0.1:3001/'; onebotToken.value = ''; onebotTokenConfigured.value = false; onebotHeartbeat.value = true; onebotHeartbeatInterval.value = 15000; qqAppID.value = ''; qqAppSecret.value = ''; qqAppSecretConfigured.value = false; qqIntents.value = 1107296769; qqAPIBase.value = ''; qqGatewayURL.value = ''; qqTokenURL.value = ''; qqGuilds.value = true; qqGuildMessages.value = true; qqGroupMessages.value = true; qqGuildAtMessages.value = true }
function onDetailChange(value: string) { detail.value = value }
function newEntry() { editing.value = null; modalError.value = ''; name.value = ''; enabled.value = true; adapterType.value = 'Onebot11'; resetAdapterForm(); detail.value = '{}'; initialDetail.value = '{}'; modal.value = true; void loadFormOptions() }
function selectAdapterType(type: string) { adapterType.value = type; if (!editing.value) resetAdapterForm() }
function onAdapterTypeChange(event: Event) { selectAdapterType((event.target as HTMLSelectElement).value) }
function edit(item: Entry) { editing.value = item; modalError.value = ''; name.value = item.name; try { const parsed = JSON.parse(item.detail || '{}'), config = parsed.config ?? parsed; adapterType.value = parsed.adapterType ?? 'Onebot11'; resetAdapterForm(); if (adapterType.value === 'QQBot') { qqAppID.value = config.AppID ?? config.appId ?? ''; qqAppSecretConfigured.value = Boolean(config.appSecretConfigured || config.AppSecret || config.appSecret); qqIntents.value = Number(config.Intents ?? 1107296769); qqGuilds.value = Boolean(qqIntents.value & 1); qqGuildMessages.value = Boolean(qqIntents.value & 512); qqGroupMessages.value = Boolean(qqIntents.value & 33554432); qqGuildAtMessages.value = Boolean(qqIntents.value & 1073741824); qqAPIBase.value = config.APIBase ?? ''; qqGatewayURL.value = config.GatewayURL ?? ''; qqTokenURL.value = config.TokenURL ?? '' } else { onebotURL.value = config.WsUrl ?? config.url ?? 'ws://127.0.0.1:3001/'; onebotTokenConfigured.value = Boolean(config.accessTokenConfigured || config.AccessToken || config.accessToken); onebotHeartbeat.value = Boolean(config.UseHeartBeat ?? config.useHeartBeat ?? true); onebotHeartbeatInterval.value = Number(config.HeartBeatInterval ?? config.heartBeatInterval ?? 15000) } } catch { modalError.value = '配置读取失败，请重新创建该适配器' }; try { const rawDetail = JSON.parse(item.detail || '{}'); detail.value = JSON.stringify(rawDetail.config ?? rawDetail, null, 2) } catch { detail.value = item.detail || '{}' }; initialDetail.value = detail.value; enabled.value = item.enabled; modal.value = true; void loadFormOptions() }
function validateURL(value: string, protocols: string[]) { const parsed = new URL(value.trim()); if (!protocols.includes(parsed.protocol) || !parsed.host) throw new Error(`地址必须使用 ${protocols.join(' 或 ')} 协议`) }
async function save() { if (!kind.value || !name.value.trim()) return; error.value = ''; modalError.value = ''; try { let config: Record<string, unknown>, saved: Entry
  if (kind.value === 'adapters') { if (adapterType.value === 'QQBot') { if (!qqAppID.value.trim()) throw new Error('AppID 不能为空'); if (!qqAppSecretConfigured.value && !qqAppSecret.value.trim()) throw new Error('AppSecret 不能为空'); qqIntents.value = (qqGuilds.value ? 1 : 0) | (qqGuildMessages.value ? 512 : 0) | (qqGroupMessages.value ? 33554432 : 0) | (qqGuildAtMessages.value ? 1073741824 : 0); if (qqIntents.value <= 0) throw new Error('至少选择一个事件权限'); if (qqAPIBase.value.trim()) validateURL(qqAPIBase.value, ['https:']); if (qqGatewayURL.value.trim()) validateURL(qqGatewayURL.value, ['wss:', 'ws:']); if (qqTokenURL.value.trim()) validateURL(qqTokenURL.value, ['https:']); config = { AppID: qqAppID.value.trim(), AppSecret: qqAppSecret.value, Intents: qqIntents.value, APIBase: qqAPIBase.value.trim(), GatewayURL: qqGatewayURL.value.trim(), TokenURL: qqTokenURL.value.trim() } } else { validateURL(onebotURL.value, ['ws:', 'wss:']); if (onebotHeartbeat.value && (!Number.isInteger(onebotHeartbeatInterval.value) || onebotHeartbeatInterval.value < 1000 || onebotHeartbeatInterval.value > 300000)) throw new Error('心跳间隔必须在 1000 到 300000 毫秒之间'); config = { WsUrl: onebotURL.value.trim(), AccessToken: onebotToken.value, UseHeartBeat: onebotHeartbeat.value, HeartBeatInterval: onebotHeartbeatInterval.value } } const payload = JSON.stringify(config); const body = JSON.stringify({ displayName: name.value.trim(), configJson: payload }); saved = editing.value ? await api<Entry>(`/api/adapter/${editing.value.id}`, { method: 'PUT', body }) : await api<Entry>('/api/adapter/create', { method: 'POST', body: JSON.stringify({ adapterType: adapterType.value, displayName: name.value.trim(), configJson: payload }) })
  }
  else { const body = { kind: kind.value, name: name.value.trim(), detail: detail.value, enabled: enabled.value }; saved = editing.value ? await api<Entry>(`/api/records/${kind.value}/${editing.value.id}`, { method: 'PUT', body: JSON.stringify(body) }) : await api<Entry>('/api/records', { method: 'POST', body: JSON.stringify(body) }) }
  entries.value = editing.value ? entries.value.map(item => item.id === saved.id ? saved : item) : [saved, ...entries.value]; modal.value = false; toast.value = editing.value ? '配置已保存' : '配置已创建'; setTimeout(() => toast.value = '', 2200); void dashboard(); if (selected.value === 'adapters') void load()
} catch (e) { modalError.value = e instanceof Error ? e.message : '保存失败' } }
async function loadFormOptions() { try { const [serverItems, adapterItems] = await Promise.all([api<Entry[]>('/api/records?kind=servers'), api<Entry[]>('/api/adapter/list')]); serverOptions.value = serverItems.map(item => ({ value: item.id, label: item.name })); adapterOptions.value = adapterItems.map(item => ({ value: item.id, label: item.name })) } catch { serverOptions.value = []; adapterOptions.value = [] } }
async function remove(item: Entry) { if (!kind.value || !confirm(`删除“${item.name}”？`)) return; try { await api(`/api/records/${kind.value}/${item.id}`, { method: 'DELETE' }); entries.value = entries.value.filter(row => row.id !== item.id); void dashboard() } catch (e) { error.value = e instanceof Error ? e.message : '删除失败' } }
async function toggle(item: Entry) { try { const updated = await api<Entry>(`/api/records/${item.kind}/${item.id}`, { method: 'PUT', body: JSON.stringify({ name: item.name, detail: item.detail, enabled: !item.enabled }) }); entries.value = entries.value.map(row => row.id === updated.id ? updated : row) } catch (e) { error.value = e instanceof Error ? e.message : '更新失败' } }
function adapterStateLabel(state?: AdapterStatus['state']) { return ({ stopped: '已停止', starting: '连接中', connected: '运行中', reconnecting: '重连中', stopping: '停止中', failed: '异常' } as const)[state ?? 'stopped'] }
async function startAdapter(item: Entry) { try { const state = adapterStatuses.value[item.id]?.state; await api(`/api/adapter/${item.id}/${state === 'connected' || state === 'reconnecting' || state === 'starting' ? 'stop' : 'start'}`, { method: 'POST' }); await loadAdapterStatuses() } catch (e) { error.value = e instanceof Error ? e.message : '操作失败'; await loadAdapterStatuses() } }
async function testAdapter(item: Entry) { error.value = ''; try { const result = await api<{ selfId?: string; nickname?: string }>(`/api/adapter/${item.id}/test`, { method: 'POST' }); toast.value = `连接成功${result.nickname ? `：${result.nickname}` : result.selfId ? `：${result.selfId}` : ''}`; setTimeout(() => toast.value = '', 2600) } catch (e) { error.value = e instanceof Error ? e.message : '连接测试失败' } }
</script>

<template>
  <div v-if="!authChecked" class="auth-screen"><div class="auth-panel"><img src="/brand.svg" alt="EasybotCE" /><p>正在连接 EasybotCE 服务…</p></div></div>
  <div v-else-if="!authenticated" class="auth-screen"><section class="auth-panel"><img src="/brand.svg" alt="EasybotCE" /><p class="auth-kicker">EASYBOTCE CONTROL CENTER</p><h1>Token 登录</h1><p class="auth-description">输入原版或启动控制台提供的登录 Token。</p><div v-if="authError" class="auth-error">{{ authError }}</div><form class="auth-form" @submit.prevent="submitAuth"><label class="field">登录 Token<input v-model="authToken" required maxlength="4096" autocomplete="current-password" type="password" placeholder="输入登录 Token" /></label><button class="btn-primary auth-submit" type="submit" :disabled="authBusy">{{ authBusy ? '请稍候…' : '进入控制台' }}</button></form></section></div>
  <div v-else class="app-shell min-h-screen bg-[#f3f6f7] text-[#26343a]">
    <aside class="sidebar fixed inset-y-0 left-0 z-10 flex w-62 flex-col px-3 py-5 text-[#d8e0e2]">
      <div class="brand mb-6 flex items-center gap-2.5 px-2"><img src="/brand.svg" alt="EasyBotCE" class="h-8 w-8 shrink-0 rounded-md" /><span class="flex flex-col"><b class="text-[15px] text-white">EasyBotCE</b><small class="text-[11px] text-[#96a7ad]">社区管理控制台</small></span><span class="ml-auto rounded-sm bg-[#31424b] px-1.5 py-0.5 text-[11px] text-[#aebbc0]">DEV</span></div>
      <div class="instance-switch mb-4 flex items-center gap-2 rounded-md p-2"><span class="flex flex-1 flex-col"><b class="text-[13px] text-white">本地实例</b><small class="text-[11px] text-[#99a7ac]">管理控制台</small></span><ChevronDown :size="14" /></div>
      <nav class="flex-1 overflow-auto"> <template v-for="group in groups" :key="group"><p class="px-2 pb-1 pt-4 text-[13px] text-[#84949a]">{{ group }}</p><button v-for="item in nav.filter(entry => entry.group === group)" :key="item.id" class="nav-link flex h-8.5 w-full items-center gap-2.5 rounded px-2 text-left text-[13px] text-[#bac5c8] hover:bg-[#243740] hover:text-white" :class="{ chosen: selected === item.id }" @click="selected = item.id"><component :is="item.icon" :size="16" /><span>{{ item.label }}</span><small v-if="item.kind === 'adapters' && counts.adapters" class="ml-auto">{{ counts.adapters }}</small></button></template></nav>
      <div class="sidebar-footer flex items-center gap-2 px-2 pt-3 text-[12px]"><i class="size-1.5 rounded-full" :class="apiOnline ? 'bg-[#45bd85]' : 'bg-[#d28564]'"></i>{{ apiOnline ? '服务在线' : '服务离线' }}<span class="ml-auto text-[11px] text-[#829198]">0.1.0-dev</span></div>
    </aside>
    <main class="main-area ml-62 min-h-screen">
      <header class="topbar sticky top-0 z-5 flex h-15 items-center justify-between px-7"><div class="flex items-center gap-3 text-[13px] text-[#879398]"><span>工作区</span><span class="text-[#c2cbce]">/</span><b class="text-[#3c4a51]">{{ title }}</b></div><div class="flex items-center gap-3"><button class="icon-btn" title="查看文档" @click="openDocs"><CircleHelp :size="17" /></button><span class="h-5 border-l border-[#e5e9ea]"></span><button class="flex items-center gap-2 text-[13px] text-[#5b686e]" title="当前登录管理员"><i class="grid size-7 place-items-center rounded bg-[#e8efeb] not-italic font-semibold text-[#52866b]">A</i>管理员<ChevronDown :size="13" /></button><button class="icon-btn" title="退出登录" @click="signOut"><LogOut :size="16" /></button></div></header>
      <div class="page-wrap mx-auto w-full max-w-390 p-7 max-sm:p-3">
        <section v-if="selected === 'overview'">
          <div class="page-heading mb-5 flex items-center justify-between gap-4"><div><div class="eyebrow mb-1.5">EASYBOTCE CONTROL CENTER</div><h1 class="text-[25px] font-semibold tracking-normal">运行总览</h1><p class="mt-1 text-[13px] text-[#7d898e]">社区接入与 Minecraft 服务配置</p></div><div class="flex items-center gap-3"><span class="api-state" :class="apiOnline ? 'is-online' : 'is-offline'"><i></i>{{ apiOnline ? 'API 在线' : 'API 离线' }}</span><button class="btn-secondary" @click="dashboard"><Activity :size="15" />刷新状态</button></div></div>
          <div v-if="error" class="mb-4 flex items-center gap-2 rounded border border-[#f0d8d3] bg-[#fcf0ee] p-2 text-[13px] text-[#a94f45]"><X :size="15" />{{ error }}<button class="ml-auto" @click="error = ''"><X :size="14" /></button></div>
          <div class="mb-4 flex flex-wrap items-center justify-between gap-2 text-[12px] text-[#718087]"><span>配置概况</span><span>最近同步 {{ updatedAt || '等待服务连接' }}</span></div>
          <div class="stats-grid mb-5 grid grid-cols-4 gap-3 max-lg:grid-cols-2 max-sm:grid-cols-1">
            <article v-for="stat in dashboardStats" :key="stat.label" class="stat-card"><span class="stat-icon" :class="stat.tone"><component :is="stat.icon" :size="18" /></span><div class="min-w-0"><span class="stat-label">{{ stat.label }}</span><strong>{{ stat.value }}</strong><small>{{ stat.note }}</small></div><ArrowUpRight :size="15" class="stat-arrow" /></article>
          </div>
          <div class="dashboard-grid grid grid-cols-[1.15fr_0.85fr] gap-4 max-lg:grid-cols-1">
            <section class="panel"><div class="panel-heading"><div><h2>接入配置</h2><p>社交平台与游戏服务器</p></div><button class="text-link" @click="selected='adapters'">管理配置 <ArrowUpRight :size="14" /></button></div><div class="connection-list divide-y divide-[#edf0f1]">
              <div v-for="item in [...adapters.map(row => ({ ...row, category: '平台适配器', icon: Radio, detailText: formatAdapterType(row) })), ...servers.map(row => ({ ...row, category: 'Minecraft 服务器', icon: Gamepad2, detailText: '桥接端配置' }))]" :key="item.id" class="connection-row"><span class="connection-icon"><component :is="item.icon" :size="17" /></span><span class="min-w-0 flex-1"><b>{{ item.name }}</b><small>{{ item.category }} · {{ item.detailText }}</small></span><span class="status" :class="(item.category === '平台适配器' ? adapterStatuses[item.id]?.state === 'connected' : bridgeStatuses[item.id]?.state === 'online') ? 'ok' : 'pending'"><i></i>{{ item.category === '平台适配器' ? adapterStateLabel(adapterStatuses[item.id]?.state) : bridgeStateLabel(bridgeStatuses[item.id]?.state) }}</span></div>
              <div v-if="adapters.length + servers.length === 0" class="dashboard-empty"><span class="empty-mark"><img src="/brand.svg" alt="" /></span><b>还没有接入配置</b><p>先添加平台适配器或 Minecraft 服务器。</p><div class="mt-3 flex justify-center gap-2"><button class="btn-secondary compact" @click="selected='adapters'; newEntry()"><Plus :size="14" />添加适配器</button><button class="btn-primary compact" @click="selected='servers'; newEntry()"><Plus :size="14" />添加服务器</button></div></div>
            </div></section>
            <section class="panel"><div class="panel-heading"><div><h2>最近活动</h2><p>服务记录与配置变更</p></div><button class="text-link" @click="selected='logs'">查看日志 <ArrowUpRight :size="14" /></button></div><div v-if="recentActivity.length" class="activity-list divide-y divide-[#edf0f1]"><div v-for="(item, index) in recentActivity" :key="`${item.time}-${index}`" class="activity-row"><i :class="`activity-dot level-${item.level}`"></i><span class="min-w-0 flex-1"><b>{{ item.message }}</b><small>{{ item.source }}</small></span><time>{{ new Date(item.time).toLocaleTimeString('zh-CN') }}</time></div></div><div v-else class="dashboard-empty activity-empty"><span class="empty-mark quiet"><Activity :size="19" /></span><b>{{ apiOnline ? '暂无活动记录' : '等待服务连接' }}</b><p>{{ apiOnline ? '服务事件和配置操作会显示在这里。' : '连接 Go API 后显示服务状态与最近事件。' }}</p></div></section>
          </div>
          <section class="setup-panel mt-4"><div class="panel-heading"><div><h2>快速开始</h2><p>按步骤完成基础接入</p></div></div><div class="setup-grid grid grid-cols-4 gap-2 max-md:grid-cols-2 max-sm:grid-cols-1">
            <button class="setup-step" @click="selected='adapters'; if (adapters.length === 0) newEntry()"><span>01</span><b>连接社交平台</b><small>{{ adapters.length ? `${adapters.length} 个配置已保存` : '添加 OneBot 11 适配器' }}</small><ArrowUpRight :size="14" /></button>
            <button class="setup-step" @click="selected='servers'; if (servers.length === 0) newEntry()"><span>02</span><b>添加 Minecraft</b><small>{{ servers.length ? `${servers.length} 个实例已保存` : '配置服务器与 Bridge' }}</small><ArrowUpRight :size="14" /></button>
            <button class="setup-step" @click="selected='groups'"><span>03</span><b>检查群组</b><small>查看已发现的聊天群组</small><ArrowUpRight :size="14" /></button>
            <button class="setup-step" @click="selected='sync-rules'; if (counts['sync-rules'] === 0) newEntry()"><span>04</span><b>设置消息同步</b><small>{{ counts['sync-rules'] ? `${counts['sync-rules']} 条规则已保存` : '创建群服消息路由' }}</small><ArrowUpRight :size="14" /></button>
          </div></section>
        </section>
        <section v-else-if="selected === 'logs'">
          <div class="mb-4 flex flex-wrap items-end justify-between gap-3"><div><div class="mb-1.5 text-[13px] text-[#89959a]">系统</div><h1 class="text-2xl font-semibold tracking-normal">运行日志</h1><p class="mt-1 text-[13px] text-[#7d898e]">{{ logStatus?.persistent ? '持久化已启用' : '仅保留内存日志' }} · 丢弃 {{ logStatus?.droppedWrites ?? 0 }} / 写入失败 {{ logStatus?.failedWrites ?? 0 }}</p></div><button class="btn-secondary" @click="load"><Activity :size="15" />刷新</button></div>
          <div class="mb-4 flex flex-wrap items-end gap-3 border-y border-[#e6ebec] bg-white p-3">
            <label class="flex h-9 items-center gap-2 text-[13px]"><input v-model="logPersistence" type="checkbox" class="accent-[#315f4a]" />持久化日志</label>
            <label class="field gap-1!">保留天数<input v-model.number="logRetentionDays" type="number" min="1" max="3650" class="h-9! w-28!" /></label>
            <label class="field gap-1!">最大记录数<input v-model.number="logMaxRows" type="number" min="1000" max="10000000" step="1000" class="h-9! w-36!" /></label>
            <button class="btn-primary compact ml-auto" :disabled="savingLogSettings" @click="saveLogSettings"><Check :size="14" />{{ savingLogSettings ? '保存中…' : '保存策略' }}</button>
          </div>
          <div class="mb-3 flex flex-wrap items-center gap-2 border-y border-[#e6ebec] bg-white p-3">
            <input v-model="logQuery" class="h-9 min-w-45 flex-1 rounded border border-[#e1e7e8] px-2.5 text-[13px] outline-none focus:border-[#739884]" placeholder="搜索日志内容" @keyup.enter="loadLogs(0)" />
            <select v-model="logLevel" class="h-9 rounded border border-[#e1e7e8] bg-white px-2 text-[13px]" aria-label="日志级别"><option value="">全部级别</option><option value="error">错误</option><option value="warn">警告</option><option value="info">信息</option><option value="debug">调试</option></select>
            <input v-model="logComponent" class="h-9 w-32 rounded border border-[#e1e7e8] px-2 text-[13px] outline-none" placeholder="模块" />
            <input v-model="logRequestID" class="h-9 w-40 rounded border border-[#e1e7e8] px-2 text-[13px] outline-none" placeholder="Request ID" />
            <label class="flex h-9 items-center gap-1.5 rounded border border-[#e1e7e8] px-2 text-[12px] text-[#879398]">从<input v-model="logFrom" type="datetime-local" class="w-39.5 text-[12px] text-[#48565d] outline-none" /></label>
            <label class="flex h-9 items-center gap-1.5 rounded border border-[#e1e7e8] px-2 text-[12px] text-[#879398]">至<input v-model="logTo" type="datetime-local" class="w-39.5 text-[12px] text-[#48565d] outline-none" /></label>
            <button class="btn-secondary compact" @click="loadLogs(0)"><Search :size="14" />筛选</button>
          </div>
          <div v-if="error" class="mb-3 flex items-center gap-2 rounded border border-[#f0d8d3] bg-[#fcf0ee] p-2 text-[13px] text-[#a94f45]"><X :size="15" />{{ error }}<button class="ml-auto" @click="error = ''"><X :size="14" /></button></div>
          <div v-if="loading" class="empty">正在读取日志…</div>
          <div v-else-if="logs.length" class="overflow-x-auto rounded-md border border-[#e4e9ea] bg-white"><table class="w-full min-w-160 border-collapse text-left"><thead class="bg-[#fafbfb] text-[13px] text-[#879398]"><tr><th>时间</th><th>级别</th><th>来源</th><th>事件</th></tr></thead><tbody><tr v-for="(item, index) in logs" :key="`${item.time}-${index}`" class="border-t border-[#edf0f1]"><td class="whitespace-nowrap text-[13px] text-[#89959a]">{{ new Date(item.time).toLocaleString('zh-CN') }}</td><td><span class="log-level" :class="`level-${item.level}`">{{ item.level.toUpperCase() }}</span></td><td class="text-[13px] text-[#718087]">{{ item.source }}</td><td class="font-mono text-[13px] text-[#48565c]">{{ item.message }}</td></tr></tbody></table></div>
          <div v-else class="empty"><b>暂无运行日志</b><p>API 操作和服务生命周期事件会显示在这里。</p></div>
          <div class="mt-3 flex items-center justify-between text-[13px] text-[#7d898e]"><span>共 {{ logsTotal.toLocaleString() }} 条</span><div class="flex gap-2"><button class="btn-secondary compact" :disabled="logsOffset === 0" @click="loadLogs(Math.max(0, logsOffset - 100))">上一页</button><button class="btn-secondary compact" :disabled="logsOffset + logs.length >= logsTotal" @click="loadLogs(logsOffset + 100)">下一页</button></div></div>
          <p class="mt-3 text-[12px] text-[#9ba5a8]">日志正文不会默认记录。关闭持久化后，新事件仅留在内存尾部，既有日志仍按保留策略清理。</p>
        </section>
        <section v-else>
          <div class="mb-6 flex items-end justify-between gap-3"><div><div class="mb-1.5 flex items-center gap-2 text-[13px] text-[#89959a]"><i class="size-1.5 rounded-full bg-[#d89e4c]"></i>{{ current.group }}</div><h1 class="text-2xl font-semibold tracking-normal">{{ title }}</h1><p class="mt-1 text-[13px] text-[#879398]">{{ descriptions[selected] }}</p></div><button class="btn-primary" @click="newEntry"><Plus :size="16" />新建配置</button></div>
          <div v-if="error" class="mb-4 flex items-center gap-2 rounded border border-[#f0d8d3] bg-[#fcf0ee] p-2 text-[13px] text-[#a94f45]"><X :size="15" />{{ error }}<button class="ml-auto" @click="error = ''"><X :size="14" /></button></div>
          <div class="mb-3 flex h-12 items-center justify-between rounded border-y border-[#e6ebec] bg-white px-3"><label class="flex flex-1 items-center gap-2 text-[#98a2a6]"><Search :size="16" /><input v-model="query" class="w-full max-w-90 border-0 bg-transparent text-[13px] text-[#39474e] outline-none placeholder:text-[#a2acaf]" placeholder="搜索名称或配置内容" /></label><div class="flex items-center gap-3"><small class="text-[13px] text-[#919da1]">{{ filtered.length }} 项</small><button class="btn-secondary compact" @click="load"><Activity :size="14" />刷新</button></div></div>
          <div v-if="loading" class="empty">正在读取配置…</div>
          <div v-else-if="filtered.length" class="overflow-x-auto rounded border border-[#e4e9ea] bg-white"><table class="w-full min-w-190 border-collapse text-left"><thead class="bg-[#fafbfb] text-[13px] text-[#929da1]"><tr><th>名称</th><th>状态</th><th>配置摘要</th><th>最近更新</th><th></th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id" class="border-t border-[#edf0f1] hover:bg-[#fbfcfc]"><td><div class="flex items-center gap-2.5 py-2"><span class="grid size-7 place-items-center rounded bg-[#eef4f0] text-[#58836d]"><component :is="current.icon" :size="15" /></span><span><b class="block text-[13px] font-semibold text-[#48565d]">{{ item.name }}</b><small class="font-mono text-[13px] text-[#a0aaad]">{{ item.id.slice(0, 8) }}</small></span></div></td><td><span v-if="selected === 'adapters'" class="status" :class="adapterStatuses[item.id]?.state === 'connected' ? 'ok' : adapterStatuses[item.id]?.state === 'failed' ? 'off' : 'pending'"><i></i>{{ adapterStateLabel(adapterStatuses[item.id]?.state) }}</span><span v-else-if="selected === 'servers'" class="status" :class="bridgeStatuses[item.id]?.state === 'online' ? 'ok' : 'pending'"><i></i>{{ bridgeStateLabel(bridgeStatuses[item.id]?.state) }}</span><button v-else class="status" :class="item.enabled ? 'ok' : 'off'" @click="toggle(item)"><i></i>{{ item.enabled ? '已启用' : '已停用' }}</button><small v-if="selected === 'adapters' && adapterStatuses[item.id]?.lastError" class="mt-1 block max-w-55 text-[12px] text-[#aa5d50]">{{ adapterStatuses[item.id]?.lastError }}</small></td><td><span class="block max-w-62.5 overflow-hidden text-ellipsis whitespace-nowrap font-mono text-[13px] text-[#849095]">{{ item.detail || '无附加配置' }}</span></td><td class="whitespace-nowrap text-[13px] text-[#909b9f]">{{ new Date(item.updatedAt).toLocaleString('zh-CN', { dateStyle: 'medium', timeStyle: 'short' }) }}</td><td><div class="flex justify-end gap-1"><template v-if="selected === 'adapters'"><button class="row-action" title="测试连接" @click="testAdapter(item)"><Activity :size="15" /></button><button class="row-action" :title="adapterStatuses[item.id]?.state === 'connected' ? '停止适配器' : '启动适配器'" @click="startAdapter(item)"><Radio :size="15" /></button></template><button class="row-action" title="编辑" @click="edit(item)"><Settings2 :size="15" /></button><button class="row-action danger" title="删除" @click="remove(item)"><Trash2 :size="15" /></button></div></td></tr></tbody></table></div>
          <div v-else class="empty"><span class="mb-3 grid size-10 place-items-center rounded-lg bg-[#eef4f0] text-[#59816e]"><component :is="current.icon" :size="21" /></span><b>{{ query ? '没有匹配的项目' : `还没有${title}配置` }}</b><p>{{ query ? '尝试其他关键词。' : '创建第一条配置以开始管理。' }}</p><button v-if="!query" class="btn-primary mt-3" @click="newEntry"><Plus :size="15" />新建配置</button></div>
          <p class="mt-3 flex items-center gap-1.5 text-[13px] text-[#9ba5a8]"><Shield :size="13" />数据保存在服务端数据库中。运行时行为依赖对应的协议或功能引擎。</p>
        </section>
      </div>
    </main>
    <div v-if="modal" class="fixed inset-0 z-20 grid place-items-center bg-[#18252c80] p-4" @click.self="modal = false"><section class="max-h-[calc(100vh-2rem)] w-full max-w-120 overflow-y-auto rounded-md border border-[#e2e8e9] bg-white p-5 shadow-2xl"><div class="mb-5 flex items-start justify-between"><div><small class="text-[13px] text-[#89959a]">{{ editing ? '编辑' : '新建' }}配置</small><h2 class="mt-1 text-[17px] font-semibold">{{ editing ? '更新' : '添加' }}{{ title }}</h2></div><button class="icon-btn" title="关闭" @click="modal = false"><X :size="18" /></button></div><form class="flex flex-col gap-3" @submit.prevent="save"><label class="field">显示名称<input v-model="name" required maxlength="120" placeholder="输入名称" /></label><label v-if="selected === 'adapters'" class="field">协议类型<select :value="adapterType" @change="onAdapterTypeChange"><option value="Onebot11">OneBot 11</option><option value="QQBot">QQ 官方 Bot</option></select></label><template v-if="selected === 'adapters' && adapterType === 'Onebot11'"><label class="field">WebSocket 地址<input v-model.trim="onebotURL" required placeholder="ws://127.0.0.1:3001/" autocomplete="url" /><small>填写协议端的正向 WebSocket 地址，支持 ws:// 和 wss://。</small></label><label class="field">AccessToken<input v-model="onebotToken" type="password" maxlength="4096" autocomplete="new-password" :placeholder="onebotTokenConfigured ? '已保存，留空则保留当前令牌' : '如协议端启用了鉴权，请输入令牌'" /><small>令牌不会回显，留空表示保留已保存令牌。</small></label><label class="flex items-start gap-3 rounded border border-[#e4e9ea] p-3 text-[13px]"><input v-model="onebotHeartbeat" type="checkbox" class="mt-0.5 accent-[#315f4a]" /><span><b class="block font-medium text-[#46545a]">启用心跳超时检测</b><small class="mt-1 block font-normal text-[#89959a]">超过检测间隔仍未收到 WebSocket 数据时，将断开并尝试重连。</small></span></label><label v-if="onebotHeartbeat" class="field">心跳间隔（毫秒）<input v-model.number="onebotHeartbeatInterval" type="number" min="1000" max="300000" step="1000" required /></label></template><template v-else-if="selected === 'adapters'"><label class="field">AppID<input v-model.trim="qqAppID" required placeholder="QQ 机器人 AppID" autocomplete="username" /></label><label class="field">AppSecret<input v-model="qqAppSecret" type="password" maxlength="4096" autocomplete="new-password" :placeholder="qqAppSecretConfigured ? '已保存，留空则保留当前密钥' : 'QQ 机器人 AppSecret'" /><small>密钥不会回显，留空表示保留已保存密钥。</small></label><fieldset class="rounded border border-[#e4e9ea] p-3"><legend class="px-1 text-[13px] font-medium text-[#46545a]">事件权限</legend><label class="mt-1 flex items-center gap-2 text-[13px]"><input v-model="qqGuilds" type="checkbox" class="accent-[#315f4a]" />频道基础事件</label><label class="mt-2 flex items-center gap-2 text-[13px]"><input v-model="qqGuildMessages" type="checkbox" class="accent-[#315f4a]" />频道消息</label><label class="mt-2 flex items-center gap-2 text-[13px]"><input v-model="qqGuildAtMessages" type="checkbox" class="accent-[#315f4a]" />频道 @ 机器人消息</label><label class="mt-2 flex items-center gap-2 text-[13px]"><input v-model="qqGroupMessages" type="checkbox" class="accent-[#315f4a]" />群和 C2C 消息</label></fieldset><details class="rounded border border-[#e4e9ea] p-3"><summary class="cursor-pointer text-[13px] font-medium text-[#46545a]">高级连接地址</summary><div class="mt-3 flex flex-col gap-3"><label class="field">API 地址<input v-model.trim="qqAPIBase" placeholder="留空使用 QQ 官方地址" /></label><label class="field">Gateway 地址<input v-model.trim="qqGatewayURL" placeholder="留空自动获取 Gateway" /></label><label class="field">Token 地址<input v-model.trim="qqTokenURL" placeholder="留空使用 QQ 官方地址" /></label></div></details></template><template v-else><div v-if="selected === 'servers' && editing" class="server-token"><div class="server-token-head"><span>桥接令牌</span><button type="button" class="text-link" @click="rotateToken">重新生成</button></div><code>{{ serverTokenOf(editing) }}</code><small>填入 Minecraft 插件的令牌字段；插件连接地址为 ws://127.0.0.1:5001/bridge</small></div><ConfigForm :initial="initialDetail" :kind="kind ?? ''" :server-options="serverOptions" :adapter-options="adapterOptions" @change="onDetailChange" /></template><label v-if="selected !== 'adapters'" class="flex items-center justify-between text-[13px]"><span>启用配置</span><input v-model="enabled" type="checkbox" class="accent-[#315f4a]" /></label><div v-if="modalError" class="rounded border border-[#f0d8d3] bg-[#fcf0ee] p-2 text-[13px] text-[#a94f45]">{{ modalError }}</div><div class="mt-2 flex justify-end gap-2 border-t border-[#edf0f0] pt-3"><button type="button" class="btn-secondary" @click="modal = false">取消</button><button class="btn-primary" type="submit"><Check :size="15" />保存配置</button></div></form></section></div>
    <Transition><div v-if="toast" class="fixed bottom-5 right-5 z-30 flex items-center gap-2 rounded bg-[#234b3e] px-3 py-2.5 text-[13px] text-white shadow-lg"><Check :size="15" />{{ toast }}</div></Transition>
  </div>
</template>
